namespace KnowledgeTracker.Domain.Authentication;
public sealed class User { public Guid Id { get; } = Guid.NewGuid(); public string Name { get; init; } = ""; public string PasswordHash { get; init; } = ""; public string NormalizedUserName => Name.Trim().ToUpperInvariant(); }
public sealed class AuthenticationSession { public Guid Id { get; } = Guid.NewGuid(); public Guid UserId { get; init; } public Guid Nonce { get; } = Guid.NewGuid(); public DateTimeOffset AuthenticatedAtUtc { get; init; } = DateTimeOffset.UtcNow; public DateTimeOffset ExpiresAtUtc { get; init; } = DateTimeOffset.UtcNow.AddHours(24); public string UserAgent { get; init; } = "unknown"; public string ClientIpAddress { get; init; } = "0.0.0.0"; public int ClientSourcePort { get; init; } public long LatestRefreshSequenceNumber { get; private set; } = 1; public bool Revoked { get; private set; } public bool TryRotate(long n) { if (Revoked || ExpiresAtUtc <= DateTimeOffset.UtcNow || n != LatestRefreshSequenceNumber) { Revoked = true; return false; } LatestRefreshSequenceNumber++; return true; } }
